create policy "Users can insert for self"
on "guardian"."code_users"
as permissive
for insert
to public
with check ((user_id = ( SELECT get_user_id() AS get_user_id)));


create policy "Disable all access"
on "guardian"."codes"
as permissive
for all
to public
using (false);



